<?php
require __DIR__.'/includes/init.php';$pageTitle='Notifikasi';$orders=$_SESSION['laundry_orders'];$notices=$_SESSION['laundry_notifications']??[];$ready=[];$overdue=[];foreach($orders as $o){if($o['status']==='ready')$ready[]=$o;if(strtotime($o['deadline'])<time()&&!in_array($o['status'],['completed','cancelled'],true))$overdue[]=$o;}require __DIR__.'/includes/header.php'; ?>
